import { useQuery } from '@tanstack/react-query';
import { crewsQuery } from '../crews/crewsQuery';
import { rolesQuery } from '../settings/settingsQuery';
import { useUser } from '../session/useUser';
import type { Person } from './peopleQuery';

const nameKey = (name: string) => name.trim().toLowerCase();

/**
 * Whether a person has a row on the people list for the signed-in user. A restricted user sees only the person whose
 * name or alias is their name (as names are compared: trimmed, ignoring case) and the people of the crews that person
 * leads or belongs to; with no such person, no one. Every other role sees everyone. Only the rows are narrowed: every
 * figure is still over everyone on the sheet.
 */
export function useListedFor(sheetId: string, people: Person[]): (person: Person) => boolean {
  const [user] = useUser();
  const roles = useQuery(rolesQuery(sheetId)).data;
  const crews = useQuery(crewsQuery(sheetId)).data ?? [];
  const name = user.trim();
  const restricted = roles?.some((r) => r.user === name && r.role === 'restricted') ?? false;
  if (!restricted) return () => true;
  const me = nameKey(name);
  const mine = me ? people.find((p) => [p.name, ...p.aliases].some((n) => nameKey(n) === me)) : undefined;
  if (!mine) return () => false;
  const seen = new Set<number>([mine.id]);
  for (const c of crews) {
    if (c.leadId === mine.id || c.memberIds.includes(mine.id)) {
      seen.add(c.leadId);
      c.memberIds.forEach((id) => seen.add(id));
    }
  }
  return (p) => seen.has(p.id);
}
  // Retired people have no row at all unless "show retired" is on; their claims still count in every total.
  const [sortBy, setSortBy] = useSortBy();
  const dues = usePeopleDueTotals(sheetId);
  const today = useSheetToday(sheetId);
  // Sorting changes only the order shown; equal keys keep list order (the sort is stable).
  const byKey: Record<SortKey, ((a: Person, b: Person) => number) | null> = {
    added: null,
    name: (a, b) => compareNames(a.name, b.name),
    grade: (a, b) => a.grade.localeCompare(b.grade),
    'due-total': (a, b) => compareDue(dues.get(a.id) ?? 'n/a', dues.get(b.id) ?? 'n/a'),
  };
  const compare = byKey[sortBy];
  // A restricted user's list has only their crews' people and themselves (useListedFor).
  const listedFor = useListedFor(sheetId, people.data ?? []);
  const filtered = (people.data ?? []).filter((p) => (showRetired || !p.retiredFrom) && listedFor(p));
  const listed = compare ? [...filtered].sort(compare) : filtered;

  return (
    <section data-testid="people">
      <h3>People</h3>
      <PersonForm sheetId={sheetId} />
      <label>
        <input
          type="checkbox"
          data-testid="show-retired"
          checked={showRetired}
          onChange={(e) => setShowRetired(e.target.checked || undefined)}
        />{' '}
        Show retired
      </label>{' '}
      <label>
        Sort by{' '}
        <select data-testid="sort-by" value={sortBy} onChange={(e) => setSortBy(e.target.value === 'added' ? undefined : (e.target.value as SortKey))}>
          {SORT_KEYS.map((k) => (
            <option key={k} value={k}>
              {k}
            </option>
          ))}
        </select>
      </label>
      <ColumnChooser />

